// Static pixel-art scenery, drawn once per theme and uploaded to the GPU as textures.
// Everything that MOVES (sky, clouds, wind, grass, flowers, petals, fireflies, water...)
// is generated by the fragment shaders in pixelShaders.js.
//
// Two layers per theme:
//   back - opaque scenery that never moves (hills, ground, trunks)
//   sway - foliage the shader bends in the wind (tree canopy, pines)
export const W = 320, H = 180;

const hs = (n) => { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); };
// MUST match `ridge()` in the shaders so grass / flowers sit exactly on the ground.
const ridge = (i, b, a, f, p) => b + Math.sin((i + p) * f) * a + Math.sin((i + p) * f * 2.3) * a * 0.4;

const layer = () => {
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const x = c.getContext('2d');
  const r = (a, b, w, h, col) => { x.fillStyle = col; x.fillRect(Math.round(a), Math.round(b), w, h); };
  return { c, r };
};
const fill = (r, yf, col) => { for (let i = 0; i < W; i++) r(i, yf(i), 1, H, col); };

// Little pine tree, drawn into `r`, tiers get narrower towards the top.
const pine = (r, x, base, h, dark, light, trunk) => {
  r(x, base - 3, 2, 4, trunk);
  for (let k = 0; k < h; k++) {
    const w = 2 * (h - k) + 1;
    r(x - (h - k) + 1, base - 4 - k * 2, w, 2, k % 2 ? dark : light);
  }
};

const SCENES = {
  meadow: () => {
    const back = layer(), sway = layer();
    fill(back.r, (i) => ridge(i, 100, 14, 0.018, 30), '#c8b8ff');
    fill(back.r, (i) => ridge(i, 118, 10, 0.03, 90), '#a5e3c0');
    fill(back.r, (i) => ridge(i, 140, 8, 0.04, 10), '#7fd49c');
    for (let i = 6; i < W; i += 23) {
      const by = Math.round(ridge(i, 140, 8, 0.04, 10)) + 2, h = 4 + (i % 3);
      back.r(i, by - 4, 2, 5, '#7a5a4a');
      for (let k = 0; k < h; k++) sway.r(i - 1 - Math.floor((h - k) / 2), by - 5 - k * 2, 4 + (h - k), 2, k % 2 ? '#4fb87a' : '#6fd49a');
    }
    fill(back.r, (i) => ridge(i, 160, 5, 0.06, 40), '#5cc183');
    return { back: back.c, sway: sway.c };
  },

  sakura: () => {
    const back = layer(), sway = layer();
    const pal = ['#ffc2dc', '#ffd6e8', '#ff9fc6', '#fff0f6'];
    fill(back.r, (i) => ridge(i, 108, 12, 0.017, 60), '#e6d6ff');
    fill(back.r, (i) => ridge(i, 128, 9, 0.028, 5), '#cdeedd');
    // trunk + branches
    for (let y = 168; y > 90; y--) {
      const w = Math.round(4 + ((y - 90) / 78) * 6), cx = 92 + Math.round(Math.sin(y / 14) * 1.5);
      back.r(cx - w / 2, y, w, 1, '#8a5a6a'); back.r(cx - w / 2, y, 1, 1, '#6a4252');
    }
    for (let k = 0; k < 26; k++) { back.r(92 + k * 1.3, 112 - k * 0.8, 3, 2, '#8a5a6a'); back.r(92 - k * 1.3, 108 - k * 0.7, 3, 2, '#8a5a6a'); }
    fill(back.r, (i) => ridge(i, 152, 3, 0.03, 0), '#bfe8b5');
    fill(back.r, () => 168, '#a6dc9f');
    // petals already lying on the ground
    for (let n = 0; n < 90; n++) {
      const x = hs(n + 3000) * W, y = ridge(x, 152, 3, 0.03, 0) + 5 + hs(n + 3100) * 22;
      back.r(x, y, 2, 1, pal[Math.floor(hs(n + 3200) * 4)]);
    }
    // canopy: darker under-layer for depth, main blossoms, then light highlights
    const blob = (i, cy, rx, ry, cols, min) => {
      const a = hs(i) * 6.283, d = Math.sqrt(hs(i + 50));
      return { x: 92 + Math.cos(a) * d * rx, y: cy + Math.sin(a) * d * ry, c: cols[Math.floor(hs(i + 7) * cols.length)], s: min + Math.floor(hs(i + 3) * 3) };
    };
    for (let i = 0; i < 150; i++) { const b = blob(i + 900, 66, 72, 38, ['#f7a8c8', '#ff9fc6', '#f48fb8'], 3); sway.r(b.x, b.y, b.s + 1, b.s, b.c); }
    for (let i = 0; i < 300; i++) { const b = blob(i, 62, 70, 38, pal, 2); sway.r(b.x, b.y, b.s + 1, b.s, b.c); }
    for (let i = 0; i < 70; i++) { const b = blob(i + 1700, 56, 62, 30, ['#fff7fb'], 1); sway.r(b.x, b.y, 2, 1, b.c); }
    return { back: back.c, sway: sway.c };
  },

  night: () => {
    const back = layer(), sway = layer();
    fill(back.r, (i) => ridge(i, 110, 14, 0.018, 70), '#3b3170');
    fill(back.r, (i) => ridge(i, 128, 10, 0.03, 20), '#2c2a5c');
    // dark pine silhouettes on the far ridge (they sway in the breeze)
    for (let n = 0; n < 11; n++) {
      const x = 8 + n * 29 + Math.floor(hs(n + 40) * 12);
      pine(sway.r, x, Math.round(ridge(x, 128, 10, 0.03, 20)) + 4, 5 + Math.floor(hs(n + 80) * 4), '#231f52', '#2b2762', '#1d1a45');
    }
    fill(back.r, (i) => ridge(i, 150, 4, 0.04, 20), '#1f3a4a');
    return { back: back.c, sway: sway.c };
  },

  sea: () => {
    const back = layer(), sway = layer();
    // small islands on the horizon (their reflection is drawn by the water shader)
    const island = (cx, w, h, col, rim) => {
      for (let i = cx - w; i <= cx + w; i++) {
        const t = 1 - Math.abs(i - cx) / w;
        const top = 100 - Math.max(1, Math.round(h * Math.pow(t, 0.75) * (0.88 + 0.12 * Math.sin(i * 0.9))));
        back.r(i, top, 1, 101 - top, col); back.r(i, top, 1, 1, rim);
      }
    };
    island(46, 44, 13, '#6a5399', '#8f70b8');
    island(118, 12, 4, '#5d4a94', '#7d62ad');
    island(268, 30, 8, '#62498f', '#8566b0');
    return { back: back.c, sway: sway.c };
  },
};

export function drawScenery(theme) { return (SCENES[theme] || SCENES.meadow)(); }
